/** @type {Handler} */
export const handler = async (input) => {
  const alteracion = input.cumple_alteracion_ovulatoria === true;
  const hiperandrogenismo = input.cumple_hiperandrogenismo_clinico === true || input.cumple_hiperandrogenismo_bioquimico === true;
  const morfologia = input.cumple_morfologia_ovarica === true;
  const diferencialesDescartados = input.diagnosticos_diferenciales_descartados === true;

  const criteriosCumplidos = [];
  if (alteracion) criteriosCumplidos.push('alteracion_ovulatoria');
  if (hiperandrogenismo) criteriosCumplidos.push('hiperandrogenismo');
  if (morfologia) criteriosCumplidos.push('morfologia_ovarica');

  const total = criteriosCumplidos.length;
  const diagnosticoConfirmado = total >= 2 && diferencialesDescartados;

  let fenotipo = null;
  if (diagnosticoConfirmado) {
    if (alteracion && hiperandrogenismo && morfologia) fenotipo = 'A';
    else if (alteracion && hiperandrogenismo) fenotipo = 'B';
    else if (hiperandrogenismo && morfologia) fenotipo = 'C';
    else if (alteracion && morfologia) fenotipo = 'D';
  }

  let conclusion = 'No cumple criterios diagnósticos de PMOS';
  if (diagnosticoConfirmado) {
    conclusion = `Compatible con PMOS fenotipo ${fenotipo}`;
  } else if (total >= 2 && !diferencialesDescartados) {
    conclusion = 'PMOS en estudio: pendiente de descarte diferencial';
  }

  return {
    cumple_hiperandrogenismo: hiperandrogenismo,
    total_criterios_rotterdam: total,
    diagnostico_confirmado: diagnosticoConfirmado,
    fenotipo_pmos: fenotipo,
    conclusion,
    criterios_cumplidos: criteriosCumplidos,
    diagnosticos_diferenciales_descartados: diferencialesDescartados
  };
};
